import { Client } from 'xrpl'
import { readFileSync } from 'node:fs'
const r = JSON.parse(readFileSync('result.json', 'utf8'))
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const ao = await c.request({ command: 'account_objects', account: 'rJDCeChoDPbXhh81J7c87dau1QfKCUSQou', ledger_index: 'validated' })
console.log('issuer objects:', ao.result.account_objects.map((o) => o.LedgerEntryType))
const i = await c.request({ command: 'ledger_entry', mpt_issuance: r.issuanceId, ledger_index: 'validated' })
const n = i.result.node
console.log('issuance', { Issuer: n.Issuer, Flags: '0x' + n.Flags.toString(16), OutstandingAmount: n.OutstandingAmount, AssetScale: n.AssetScale })
for (const [k, a] of Object.entries(r.holders)) {
  const t = await c.request({ command: 'ledger_entry', mptoken: { mpt_issuance_id: r.issuanceId, account: a }, ledger_index: 'validated' })
  console.log(k, a, { MPTAmount: t.result.node.MPTAmount ?? '0', Flags: t.result.node.Flags })
}
await c.disconnect()

